def shifted_mismatch(X):
 mism=[]; valid=[]
 for r in range(30):
  for c in range(30):
   rr,cc=31-r,31-c
   if rr<30 and cc<30 and X[r,c]!=8 and X[rr,cc]!=8:
    valid.append((r,c));
    if X[r,c]!=X[rr,cc]: mism.append((r,c, int(X[r,c]),int(X[rr,cc])))
 return len(valid),mism
