def symm_match(X, mapper):
 bad=[]; n=0
 for r in range(30):
  for c in range(30):
   rr,cc=mapper(r,c)
   if 0<=rr<30 and 0<=cc<30 and X[r,c]!=8 and X[rr,cc]!=8:
    n+=1
    if X[r,c]!=X[rr,cc]: bad.append((r,c,int(X[r,c]),rr,cc,int(X[rr,cc])))
 return n,bad
